BEGIN;
DO $$
DECLARE p uuid:=uuidv7();p2 uuid:=uuidv7();p3 uuid:=uuidv7();s uuid:=uuidv7();s2 uuid:=uuidv7();s3 uuid:=uuidv7();a uuid;d uuid;r jsonb;f uuid:=uuidv7();blocked boolean;v uuid;
BEGIN
 INSERT INTO person(id,kisa_kimlik,ad,soyad,gorunen_ad,orcid,sahiplenildi,sahiplenme_tarihi,kurum_beyan) VALUES(p,'reviewa1','Owner','One','Owner One','0000-0000-0000-1000',true,now(),'Test University'),(p2,'reviewa2','Reader','Two','Reader Two','0000-0000-0000-1010',true,now(),'Test University'),(p3,'reviewa3','Other','Three','Other Three','0000-0000-0000-1021',true,now(),'Test University');
 INSERT INTO orcid_session(id,person_id,orcid,gorunen_ad,belirtec_ozeti,bitis) SELECT x.sid,x.pid,p.orcid,p.gorunen_ad,sha256(convert_to(x.sid::text,'UTF8')),now()+interval '1 hour' FROM (VALUES(s,p),(s2,p2),(s3,p3)) x(sid,pid) JOIN person p ON p.id=x.pid;
 INSERT INTO announcement(sahip_id,ham_metin,yayin_metni,sure_hafta,bitis) VALUES(p,'An original academic collaboration draft','An original academic collaboration text',4,now()+interval '4 weeks') RETURNING id INTO a;
 INSERT INTO research_area(id,sema,ad_tr,normalize_ad,slug) VALUES(f,'avesis','Review skill','review skill','ci-review-skill');
 PERFORM yarenler_duyuru_yetkinlik(s,a,ARRAY[f]);
 IF NOT EXISTS(SELECT 1 FROM announcement_skill WHERE announcement_id=a AND area_id=f) THEN RAISE EXCEPTION 'Wanted skill not saved';END IF;
 blocked:=false;BEGIN PERFORM yarenler_duyuru_yetkinlik(s2,a,ARRAY[f]);EXCEPTION WHEN SQLSTATE 'YA030' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Another person edited wanted skills';END IF;
 blocked:=false;BEGIN PERFORM yarenler_duyuru_yetkinlik(s,a,ARRAY[f,f,f,f]);EXCEPTION WHEN SQLSTATE 'YA031' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'More than three wanted skills accepted';END IF;
 PERFORM yarenler_duyuru_ilgi(s2,(SELECT kisa_kimlik FROM announcement WHERE id=a),true);
 PERFORM yarenler_duyuru_ilgi(s2,(SELECT kisa_kimlik FROM announcement WHERE id=a),true);
 IF (SELECT count(*) FROM announcement_interest WHERE announcement_id=a AND person_id=p2)<>1 THEN RAISE EXCEPTION 'Duplicate interest';END IF;
 IF (SELECT adet FROM announcement_interest_usage WHERE person_id=p2)<>1 THEN RAISE EXCEPTION 'Idempotent interest used extra allowance';END IF;
 r:=yarenler_duyuru_ilgilenenler(s);
 IF jsonb_array_length(r)<>1 OR r->0->>'person_short'<>'reviewa2' THEN RAISE EXCEPTION 'Owner cannot see interest';END IF;
 IF yarenler_duyuru_ilgilenenler(s3)<>'[]'::jsonb THEN RAISE EXCEPTION 'Private interest list leaked to another member';END IF;
 blocked:=false;BEGIN PERFORM yarenler_duyuru_ilgi(s,(SELECT kisa_kimlik FROM announcement WHERE id=a),true);EXCEPTION WHEN SQLSTATE 'YA031' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Owner liked own announcement';END IF;
 PERFORM yarenler_duyuru_ilgi(s2,(SELECT kisa_kimlik FROM announcement WHERE id=a),false);
 IF EXISTS(SELECT 1 FROM announcement_interest WHERE person_id=p2) THEN RAISE EXCEPTION 'Withdraw did not remove visibility';END IF;
 UPDATE announcement_interest_usage SET adet=20 WHERE person_id=p2;
 blocked:=false;BEGIN PERFORM yarenler_duyuru_ilgi(s2,(SELECT kisa_kimlik FROM announcement WHERE id=a),true);EXCEPTION WHEN SQLSTATE 'YA033' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Withdraw reset daily abuse limit';END IF;
 d:=yarenler_duyuru_rezervasyon(p,a);
 INSERT INTO duyuru_yasagi(person_id,bitis,neden) VALUES(p,now()+interval '7 days','yonetici');
 blocked:=false;BEGIN PERFORM yarenler_duyuru_revize(d,p,'A forbidden replacement text','[]','{}');EXCEPTION WHEN SQLSTATE 'YA022' THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Ban during review did not prevent revision';END IF;
 DELETE FROM duyuru_yasagi WHERE person_id=p;
 UPDATE duyuru_denemesi SET gun=yarenler_bugun()-1 WHERE id=d;
 r:=yarenler_duyuru_denetim_sonucu(d,p,'ret','reklam_spam','Potentially identifying free text',NULL,'Private rejected revision','test-model','198.51.100.1','Browser 1',7);
 v:=(r->>'ihlal')::uuid;
 IF (SELECT gun FROM duyuru_denemesi WHERE id=d)<>yarenler_bugun() THEN RAISE EXCEPTION 'Midnight result used a different day from publication';END IF;
 IF EXISTS(SELECT 1 FROM icerik_ihlali WHERE id=v AND (metin IS NOT NULL OR ip IS NOT NULL OR ad IS NOT NULL OR orcid IS NOT NULL OR kurum IS NOT NULL OR user_agent IS NOT NULL OR gerekce<>'İçerik denetiminde reddedildi.')) THEN RAISE EXCEPTION 'Ordinary rejection retained private snapshot';END IF;
 IF (SELECT yayin_metni FROM announcement WHERE id=a)<>'An original academic collaboration text' OR (SELECT revizyon_tarihi IS NOT NULL FROM announcement WHERE id=a) THEN RAISE EXCEPTION 'Rejected revision changed published content';END IF;
 UPDATE icerik_ihlali SET olusturma=now()-interval '31 days' WHERE id=v;
 PERFORM yarenler_ihlal_temizle(180);
 IF EXISTS(SELECT 1 FROM icerik_ihlali WHERE id=v) THEN RAISE EXCEPTION 'Ordinary rejection survived 30-day retention';END IF;
 IF has_table_privilege('yarenler_web','announcement_interest','SELECT') OR has_table_privilege('yarenler_auth','announcement_interest','SELECT') THEN RAISE EXCEPTION 'Private interest list table exposed';END IF;
END $$;
ROLLBACK;
